"use strict";
// Référence complète, version anglaise (miroir de REF_FR dans guide-ref-fr.js : mêmes rubriques, mêmes blocs, mêmes segments de code).
// Quatre parties (`part`), dans cet ordre : set (réglages et commandes), write (ce que l'on écrit), gen (ce que l'Âge produit seul), relto.
// Blocs : { p } | { h } | { ul } | { code } | { note: encadré « comment l'écrire » } | { table: { head, rows } }
// `check` (facultatif, pour test/reference.test.js) : "blocks" = chaque `identifiant` est un bloc qui s'écrit ;
// "products" = chaque produit est un bloc qui ne s'écrit pas ; "phys" = la colonne 2 du tableau est une ligne de valeur lisible.
const REF_EN = [
  // ---- Réglages ---------------------------------------------------------------------------------------------------
  { id: "setref", part: "set", icon: "sliders-horizontal", title: "All settings", body: [
    { p: "Settings › Age Writer › Extensions, in seven pages. Defaults in brackets." },
    { h: "Books & covers" },
    { ul: ["Leather book theme (on) · Cover tab (on)", "Open the book in: main tab (default), window, side panel", "When a book opens: cover (default) or keep the current tab", "Book covers: auto (default), ornate, classic, sober, plain", "Linking book in 3 pages (on)"] },
    { h: "Sounds" },
    { ul: ["Sounds (all) (on) · Volume (0.35)", "Book: Book sound · Clasp clicks · Page turning (all on)", "Age: Linking sound (on)", "Relto: Sounds of the close-up views · Imager hum (on); optional sound files for the pond, fireplace, purring, meow", "Hub soundscape: minimal / zen (default) / full · Relto volume (0.6)"] },
    { h: "Linking window" },
    { ul: ["Tabs in the Age block (on)", "Window rendering: generative (default, the world the Imager shows) / classic", "Window size: normal / large (default) / extra large", "Linking window effect: classic (default), static, ripple, sweep, random, off · Effect strength (1, from 0.2 to 2)", "Uncertain links (on)"] },
    { h: "D'ni & numbers" },
    { ul: ["Language of the extensions: auto, English, Français", "Numerals: auto / font / glyph file / drawn · Numeral font (name)", "Show numbers (on) · Names in D'ni script (on)", "Relto in tabs (on) · D'ni time in the Relto (on) · Frame around clickable zones (off) · Turning pages in the books (on)", "Surveyor's notes (Imager): full / words only (default) / off · Lens hints (Imager): on (default) / off"] },
    { h: "Ages & mechanics" },
    { ul: ["Law of change (on) · Minutes before the ink dries (15, from 1 to 120) · Healing per day (0.05, from 0 to 0.3)", "Fissure opening (7 days, from 0 to 30)", "Mechanisms: draw (default) / written only · Solitude: off / balanced (default) / strong", "Physics of the Ages: easy (default) / strict / off · Physics severity (1, from 0.5 to 2)", "Way of the instruments (telescope and Imager): easy (default) / the Art of the Guild"] },
    { h: "Folders" },
    { ul: ["Maintenance tools (off): the ribbon's wrench icon (debugging, repairs, library); the commands stay in the palette", "Journal folder (empty = next to the Age's note) · Hub folder (`Ages`)"] },
    { h: "Drawing & library (engine settings)" },
    { ul: ["Update Age data automatically (off): write the properties on every save", "Draw the linking panel from the Age (on): paint the glass from the Age", "Let the book draw what it leaves open (on): draw the open slots · How much the book draws: little / normal (default) / a lot", "How much a clash steers the draw: none / gentle / moderate (default) / strong", "Library folder (empty = whole vault) · Default linking panel image"] },
  ] },
  { id: "dni", part: "set", icon: "languages", title: "D'ni numerals and text", body: [
    { p: "Base-25 numbers (Age number, coordinates, seed, puzzles). “Numerals” setting: auto, font, glyph file, drawn. Levels: an installed font (family “Dni”) or a .ttf/.otf file from the vault; a local glyph file `dni-numerals.local.json`; numerals drawn by the plugin (always available)." },
    { p: "The fan font is neither supplied nor bundled. D'ni text (setting “Names in D'ni script”, font required): the refuge name, Age plate, journal title, cover, `inscription:`, and inline `` `dni:text` ``. Free block ```` ```dni ```` (one line per number or word). Without a font: Latin italics, never fake D'ni." },
  ] },
  { id: "cmd", part: "set", icon: "terminal", title: "Commands", body: [
    { p: "The ribbon (the column of icons on the left; on a phone, the left menu) has two Age Writer icons, each opening a menu. The **book**, Age Writer: everything for playing and writing. The **wrench**, maintenance and tests: debugging, repair and library tools, used only when needed; it only shows with the “Maintenance tools” setting (off by default). A command that does not apply where you are (no Age open, for example) is greyed out. All of them stay in the command palette too (Ctrl/Cmd + P), by typing a few words of their name." },
    { h: "The book: Age Writer" },
    { ul: ["**First**: open the Relto (the Relto book, or the last Relto visited, depending on the setting)", "**The Relto**: Open the Relto book · Open the Relto · Open the Relto view (large) · Create a Relto page", "**The open Age**: Open this Age as a book · Create the exploration journal for this Age · Save this Age's book cover (SVG) · Save this Age's window as a GIF · Update Age data in this note · Generate a random Age (a coherent, stable world in a new note) · Generate the Age map (canvas)", "**The books**: Open the Age Writer guide · Open the Age Writer full reference · Open the book of glyphs · Open a library note (Age blocks / Relto pages)", "**The story**: Start the story · Story: a hint for the current chapter · Story: check progress now · Story: next chapter", "**The sound**: Stop the soundscape"] },
    { h: "The wrench: maintenance and tests" },
    { ul: ["**Tests**: Mutation: advance four days on the open Age (forces a union, even on an Age that cannot mutate) · Machine: tests (fill the hoppers, give five pellets of a colour, finish the batch now, empty everything) · D'ni numerals: diagnostic report (the font, the missing digits, the measured posts)", "**Repairs**: Story: repair chapter notes · Story: restart the current chapter · Give this Age back the world of its former name (an Age renamed before the plugin kept seeds) · Forget the Great Zero (sync the telescope again) · Clean the star chart (forget the stars of Ages no longer on the shelf) · Empty the chamber of memories", "**Library**: Update Age data in every note · Create an Age library note · Copy the built-in content into a library note (to edit it) · Reload the Age library", "**The Relto button**: Relto button: switch between the Relto book and the last Relto visited (what the first menu entry does)"] },
    { p: "In the guide: the search field keeps only the topics that contain the words (accents do not matter) and highlights them; ← and → turn the topics; a long topic opens on the list of its subheadings, one click away." },
    { p: "On first launch, a “Age Writer — Bienvenue” (or “Welcome”) note with an annotated example Age is created once, never in a vault that already has Ages." },
    { p: "Known limits: the law of change stores its state by note name; a note with several `age` blocks draws one world per block; the engine's content is in English; no GIF export in generative rendering." },
  ] },

  // ---- Ce que l'on écrit ----------------------------------------------------------------------------------------
  { id: "syntax", part: "write", icon: "pencil", title: "How to write an Age", body: [
    { p: "An Age is a code block of type `age` in a note. Each line is read on its own, and there are only three kinds of line. A whole Age can be this short:" },
    { code: "```age\nsingle_sun\nwater\nfern\nmass: 0.8\nmany: fern\nreturn: [[Hub]]\n```" },
    { h: "1 · A block: one identifier alone on its line" },
    { p: "A block is a page of the world (a sun, water, ferns, a ruin…). Write its identifier exactly as this reference lists it: lowercase, with underscores, nothing before or after it, one block per line." },
    { code: "```age\ntwin_suns\nlava\ngreat_tree\n```" },
    { note: "The lists are sorted under headings (Stars, Geology, Fauna…). A heading is only a label: never write it. `stars: twin_suns` is an ink blot; `twin_suns` alone on its line is right." },
    { h: "2 · A key: value line" },
    { p: "A key, a colon, a value. Used for links, the seed, the physics values, the window and the state of the book. Most keys also accept `=` instead of the colon." },
    { code: "```age\nseed: 42\nlink: [[Sunder Reach]]\nage: 3.5\nwindow_style: generative\ndamaged_pages = 2\n```" },
    { h: "3 · A list line: a key, then several names" },
    { p: "A key followed by several blocks or names separated by commas. Used by quantities and mechanisms." },
    { code: "```age\nmany: ruins, trees\nfew: rain\nmechanism: water_valve, telescope\n```" },
    { h: "Good to know" },
    { ul: [
      "Empty lines and lines starting with `#` are ignored: use them as notes to yourself",
      "A line the plugin does not recognise is an **ink blot**: it costs 10 points of cosmological stability, and the generative window paints it from its words. Mind the spelling and the case: `Water` and `twin suns` are ink blots",
      "`water` alone on its line is a block (the world has water); `water: 2` is a physics value (how much water). The colon makes the difference",
      "Whatever you leave unwritten is drawn from the note's name (and its `seed:` line), always the same way: see “Stability and the draw”",
      "Blocks can also be added from the palette of the book view (command “Open this Age as a book”)"] },
  ] },
  { id: "modifiers", part: "write", icon: "sliders-vertical", title: "Modifiers at a glance", body: [
    {"p": "Blocks say what the world holds. A few other lines adjust it: how much of it, how often, how big the world is. This sheet says which line goes with which block; the topics named at the end of each row have the details."},
    {"table": {"head": ["Line", "What it does", "Works on", "Example"], "rows": [["`many:` · `few:` · `normal:`", "More or less of something already written: the block costs twice (`many`) or 40% (`few`) of its weight, and the generative window draws more or fewer of it. Creates nothing.", "Any block written in the Age, or a group: `ruins`, `trees`, `water`, `rain`, `fog`, `wind`, `moths`, `glow`, `riches`, `scars`, `clouds`, `stars`", "`few: rain` · `rain: few` · `many: ruins, trees` (see “Quantities”)"], ["`block: often, dawn`", "Weather that comes and goes: how often (`always`, `often`, `sometimes`, `rarely`, `1/10`, `30%`) and at which hours (`dawn`… `night`). The window and the description follow; stability does not change.", "Weather blocks only: `wind`, `rain`, `fog`, `lightning`, `heat`, `drizzle`, `snow`, `rainbow`, `tornado`", "`drizzle: often, dawn` · `fog: 1/10, night` (see “Weather lines”)"], ["`size:`", "How big the world is: it scales how much a clash between sky and matter costs. `small` 0.6 · `medium` 1 (default) · `large` 1.5.", "The whole Age", "`size: large` (see “Dosing, rigour and depth”)"], ["`mass:`, `age:`, `core:`, `atmosphere:`, `water:`…", "The planet's numbers (see the table in “Physics values”). A number fixes a value; a word is a claim the physics checks.", "The whole Age", "`mass: 1.2` · `core: liquid`"], ["`seed:`", "Changes what the Age draws for the slots you left open. Same note + same seed = same world.", "The whole Age", "`seed: 42`"], ["`moons:`", "How many moons the window draws, from 0 to 5.", "The whole Age (window)", "`moons: 2`"], ["`window_style:`, `window_size:`, `fx:`, `day_length:`, `year_length:`", "How the linking window looks and how fast its sun moves.", "The whole Age (window)", "`fx: ripple` (see “Window lines”)"], ["`cover:`", "How ornate the book's cover is.", "The whole Age (book)", "`cover: sober`"], ["`link:`, `return:`, `panel:`", "The books that lead out and back, and your own window image.", "The whole Age", "`link: [[Glass Marsh]]`"], ["`trap book`, `damaged_pages =`, `removed_pages =`", "A book with no way home, or one that is damaged or torn.", "The whole Age (the link)", "`damaged_pages = 2`"], ["`mechanism:`", "Abandoned machines with a puzzle, shown in the Details tab.", "The whole Age", "`mechanism: water_valve`"]]}},
    {"h": "Quantity or frequency?"},
    {"p": "`few` and `rarely` look alike but are two different things. **`rain: few`** (or `few: rain`) is a **quantity**: a lighter rain, a block that costs less. **`rain: rarely`** is a **frequency**: the rain is there only now and then (about 15% of the time). Both can be written together, on two lines: `rain: rarely, night` and `few: rain`. A bare `rain` is always there, and `rain: always` says the same."},
    {"h": "One word, three lines"},
    {"ul": ["`water` alone on its line: a **block** (the world has water)", "`water: 2`: a **physics value** (how much water the planet holds)", "`water: few`: a **quantity** (little of the water that is written; it does nothing if `water` is not written)"]},
    {"p": "The colon alone does not tell them apart: what comes after it does (a number, a quantity word, a frequency or an hour). The order of the lines never matters."},
  ] },
  { id: "sky", part: "write", icon: "sun", title: "Sky blocks", check: "blocks", body: [
    { note: "Every name in backticks below is a block: write it as-is, alone on its line. The number in brackets is its cost in stability points (on the cosmological axis); a + gives points back." },
    { code: "```age\ntwin_suns\nred_sun\nwide_binary_orbit\nauroras\nplanet_rings\nmountains\n```" },
    { h: "Stars (drawn if you write none)" },
    { ul: ["`single_sun` (−5): one sun", "`twin_suns` (−10): two suns", "`starless` (−10): no sun at all; only the ground's own heat, and green life struggles"] },
    { h: "Moon (sometimes drawn)" },
    { ul: ["`companion_moon` (+3): a moon in the sky; the line `moons: 3` draws more of them", "`moon: small` · `moon: large` · `moon: distant` · `moon: close`, or two words (`moon: small, distant`); also `lune: petite, grande, lointaine, proche`. The line qualifies the written moon and costs nothing. Small or distant, it no longer steadies the world's axis: an erratic cycle becomes possible again, and the tide weakens. Large or close, the tide heats the interior more. A distant moon needs a planet with enough grip to keep it: heavy enough, or far enough from its star (otherwise a light clash). The window draws it smaller or larger"] },
    { h: "Day cycle (drawn if you write none)" },
    { ul: ["`steady_cycle` (−5): regular days and nights", "`erratic_cycle` (−8): days and nights of uneven length", "`frozen_cycle` (−10): the sky never moves; one face always to the sun (it clashes strongly with `stable_orbit`, `shifting_orbit` and `chaotic_orbit`)"] },
    { h: "Orbit of two suns (never drawn)" },
    { p: "These describe how two suns move: write them with `twin_suns`. With one sun or none they clash." },
    { ul: ["`close_binary_orbit` (−5): the planet circles one sun, the other stays far away", "`wide_binary_orbit` (−5): the planet circles both suns from far out", "`stable_orbit` (−5): a steady round; with two suns it also needs `close_binary_orbit` or `wide_binary_orbit`", "`shifting_orbit` (−8): the round drifts, eclipses change", "`chaotic_orbit` (−10): no rule at all (it clashes strongly with `frozen_cycle` and `starless`)"] },
    { h: "Phenomena (sometimes drawn)" },
    { ul: ["`auroras` (−5): lights in the sky; the physics wants a magnetic field", "`recurring_eclipses` (−7): needs two suns, or one sun and `companion_moon`", "`permanent_veil` (−6): a sky always overcast; only 30% of the light gets through", "`starfall` (−5): showers of shooting stars"] },
    { h: "Sky bodies (never drawn)" },
    { ul: ["`asteroid_belt` (−7): small rocks in an arc", "`asteroid_field` (−9): big boulders, one of which sometimes falls", "`planet_rings` (−2): a ringed giant fills the sky; this world is one of its moons, warmed by its tides", "`comet` (−4): a long-tailed comet"] },
    { p: "A belt or a field threatens ruins, trees and water; a field weighs more than a belt and falls hard on a bridge." },
    { h: "Dead stars (never drawn)" },
    { p: "These are already out there, written or not: every region of space holds them or not, and nearby stars share them. Writing one only describes it: the book then names a world whose star has one nearby (if the star you wrote has none, the world is placed by another star that does; rewriting moves the world). At the telescope they perturb the Great Zero's signal (see the Relto part)." },
    { ul: ["`pulsar` (−6): a fast-spinning dead star whose beam sweeps the sky; a second, faster beat crosses the Zero's pulse; hard on life (light, ecological)", "`neutron_star` (−5): a small, heavy, blue-white ember; a second, slower beat drags under the Zero's", "`black_hole` (−8): a ring of light around an empty dark; it bends the Zero's light (the direction seen from the Age is wrong); it unsettles `stable_orbit` (light)"] },
    { h: "Sun colours (never drawn)" },
    { p: "A colour changes the sun you already have. Two different colours need `twin_suns`; any colour clashes with `starless`." },
    { ul: ["`red_sun` (−3): a red dwarf; it warms more than it lights, and close worlds often keep one face to it", "`orange_sun` (−2), `white_sun` (−2): a smaller or a bigger star than the Sun", "`blue_sun` (−4): a giant star that lives too briefly for evolution", "`violet_sun` (−5): a hot star rich in ultraviolet; life in the open needs thick air", "`green_sun` (−3): a sun-like star with tinted light (purple foliage)", "`black_sun` (−6): a brown dwarf; nearly all its light is infrared: grey, dark days, a black disc rimmed with red, a very tight orbit"] },
    { p: "Green and violet suns do not exist among real stars: in strict physics mode they cost a little Art (metaphysical axis)." },
    { h: "World types (−2 each, never drawn)" },
    { p: "`frozen_world`, `lava_world`, `desert_world`, `ocean_world`, `jungle_world`, `cavern_world`. They paint the whole window and steer the physics; they create no matter. Two world types clash strongly, and each clashes with its opposites (`frozen_world` with `lava`, `lava_world` with `deep_cold`…). **`cavern_world`** is a world under a lid of rock: no sun, and no `rain`, `lightning` or `wind` (strong contradictions). The cold, the heat and the light of the outside get in only in part, according to the vault: thick rock (`stone`, `iron`, `crystal`) lets in a quarter to a half, ordinary ground a third to three quarters, loose ground (`sand`, `ash`, silt) half to nearly all, the bigger the world (`size:`) the more. A loose vault under a large world is tired, and that costs from balanced rigour up." },
    { h: "The planet in words (never drawn)" },
    { p: "Words instead of numbers for the physics values; each one stands for a range." },
    { ul: ["`close_orbit` (−5) / `distant_orbit` (−5): 1.2 to 2.6 times Earth's sunlight, or 0.12 to 0.6 (they clash with each other)", "`young_world` (−6) / `ancient_world` (−4): 50 to 800 million years old, interior burning; or 7 to 12 billion, interior cooled (needs a long-lived star)", "`heavy_world` (−5) / `light_world` (−4): 2.5 to 8 Earth masses (strong gravity, low mountains), or 0.06 to 0.35 (weak gravity, leaking air)"] },
    { h: "Terrain (never drawn)" },
    { ul: ["`plains` (−2): wide, low land; two flat ranges in the window", "`hills` (−2): soft, rolling land; three gentle ranges", "`mountains` (−3): tall peaks; four sharp ranges (they clash strongly with `plains`, less with `hills`)", "`canyon` (−3): a deep gorge; two sharp ranges", "`river` (−2), `delta` (−3), `lake` (−2), `marsh` (−2): water and a shore in the window (the marsh adds mist); they clash with `desert_world` and `lava_world`"] },
    { p: "There is no desert block: use `desert_world` or `sand`." },
  ] },
  { id: "matter", part: "write", icon: "layers", title: "Matter blocks", check: "blocks", body: [
    { note: "Every name in backticks below is a block: write it as-is, alone on its line. “Drawn” means the Age may add it by itself when you leave that slot open; the others only exist if you write them. The number in brackets is the stability cost on the block's own axis." },
    { code: "```age\nwater\nsand\nfern\ngrazer\ntablet\ngold\nbarren_soil\n```" },
    { h: "Geology" },
    { ul: ["Ground (one drawn at most): `water` (−3), `stone` (−2), `sand` (−2), `deep_cold` (−5), `lava` (−6)", "Minerals (sometimes drawn): `salt` (−3), `ash` (−2), `iron` (−3), `crystal` (−4)", "Never drawn: `strange_stone` (−8), a catalyst that turns reaction products into rare variants; `pressure` (−5), crushing depth"] },
    { h: "Ways home (geological)" },
    { ul: ["Drawn, one at most: `fissure` (in the open, or underwater if there is water), `submarine_fissure` (only with water), `cave_fissure` (deep in a cavern); −2 each", "`no_fissure` (−2): there is none; never drawn"] },
    { h: "Weather" },
    { ul: ["Sometimes drawn: `wind` (−3), `rain` (−3), `fog` (−3), `lightning` (−5), `heat` (−4)", "Never drawn: `drizzle` (−2), a fine rain that comes and goes; `snow` (−3), it falls without a sound; `rainbow` (−2), it needs a sun; `tornado` (−6), a dark spinning column"] },
    { h: "Life (ecological)" },
    { ul: ["Flora, sometimes drawn: `spore` (−2), `seed` (−2), `fern` (−2), `vine` (−3), `great_tree` (−5); never drawn: `flowers` (−2), with `fog` they scent the mist, with `wind` they fall as petals; `grass` (−2), green land that the wind combs in long waves (a grassy shore by water, tall grass in the foreground); with `flowers` it grows into a meadow, tall grass to the horizon with flowers through it", "Fauna, sometimes drawn: `moth` (−3), `grazer` (−3), `burrower` (−3), `hunter` (−5), `drifter` (−4)", "Never drawn: `kelp` (−2), an underwater forest; `coral` (−3), a bright reef in warm water; `spiders` (−3), silk spinners shy of light, they need prey"] },
    { ul: ["Micro-life, never drawn: `plankton` (−2), green and teeming in the water; `microbial_mat` (−2), a slick mat that lives on heat and stone; `glow_algae` (−2), a cold algae that glows in the water, a lamp for the caverns; `pellet` (−2), a capsule of nutrients written into the world: `few: pellet` feeds what grows, `many: pellet` burns it (nothing to do with the Relto's machine: Ages do not give pellets, they give its ingredients); `mycelium` (−2), the threads that return the dead to the soil (with `water`, it fruits as mushrooms)", "Shrubs, never drawn: `berry_shrub` (−2), `thorn_bush` (−2), `heath_shrub` (−2): the steps between the small plants and the trees, one for each ground", "Fauna by habitat, never drawn: `shoal` (−3, a herbivore of the water), `raptor` (−4, a hunter of the air), `deep_hunter` (−5, a hunter of the water), `cave_stalker` (−5, a hunter of the caves), `carrion_beetle` (−2, eats the dead), `bee` (−3, with `flowers` it makes humming blooms). `hunter` stays the all-round carnivore: it closes any loop, but less well than a specialist", "Ground born of life, never drawn: `earth` (−2), `humus` (−1), `peat` (−3). They need an old enough world; the engine makes them itself from lichen, `earth` and `mycelium`, or from moss and `marsh`", "**Laws of life** (a sentence in the panel, and a cost only from balanced rigour up): the loop must close (something must return the dead to the soil: `mycelium`, pale fungus, soil bacteria, `carrion_beetle`, or a side-job such as `moth`, `hunter`, `burrower`); the large rests on the small (a microbe, a mould, a spore); flowers want a pollinator; a big tree needs ground that can bear it, and roots need earth; plankton needs light and a microbial mat needs heat or chemistry", "**The sickness of the living**: when a role that feeds (the plants, or what returns the dead to the soil) is held by a single species and animals depend on it, the chain holds by a pair and falls sick. It never happens at gentle rigour; at balanced the seed decides (about one such world in three); from strict up it is certain. It is a light scar (normal if several animals depend on it): a few points, a sentence, yellowed patches in the window. It never takes a stable world below 75% (its cost stops there); an Age already unstable sinks. A second species in the role cures it. A plant alone, with nothing feeding on it, never falls sick"] },
    { h: "Ruins and places (metaphysical)" },
    { ul: ["Sometimes drawn: `tablet` (−3), `lamp` (−3), `bridge` (−3), `door` (−4), `book` (−4)", "Never drawn: `library` (−3), a shut library full of books; `ruined_library` (−4), roofless; `garden` (−3), a maze of flowers"] },
    { p: "Ruins and places say that someone passed through: the physics forgives what builders could have brought (trees under a star too young), never impossible life (no light, no air, a deadly temperature)." },
    { h: "Riches and scars (never drawn)" },
    { ul: ["Riches: `gold` (−9), `silver` (−6), `gems` (−7), `rare_ore` (−8), `pearls` (−5), `copper` (−3)", "Scars, free on their own: `scorched_surface`, `poisoned_air`, `barren_soil`, `bitter_water`, `hollowed_ground`, `ashen_sky` (geological); `held_rain` (weather: clouds that keep their rain); `mute_ruins` (ruins: they no longer say anything)"] },
    { p: "Each scar gives back 3 points of the riches' cost, up to 75% of it: a rich world is never free. Without riches, a written scar does nothing." },
    { h: "Scars the world keeps from its draw" },
    { p: "What is drawn is the part of the world trying to settle; you did not choose it. A light clash that touches a drawn page costs nothing. A medium or strong one no longer costs its full price: the world forms anyway, but keeps a scar, one per axis, that says what went wrong (an ash sky for the sky, scorched ground or bitter water for the soil, barren soil for life, held rain for the weather, mute ruins for the ruins). It costs a little." },
    { ul: ["*Light* scar: a medium clash. *Normal*: a strong clash. *Deep*: several strong clashes on the same axis. The window draws it fainter or deeper", "A kept scar also eases the riches' cost, a little more when it is deep (2.4, 3 or 3.75 points), always within the 75% limit", "It heals by writing: write your own value in the slot of the drawn page that clashes so nothing clashing is drawn there, and the scar goes. Keeping the page (✓) makes it yours: the clash then costs its full price", "Clashes between pages you wrote stay whole: that is your choice"] },
    { h: "Interior, air, acid (geological, never drawn)" },
    { ul: ["`molten_core` (−3) / `dead_core` (−4): a molten core (magnetic field), or a dead one", "`geysers` (−4): hot springs; they need water and inner heat", "`rifts` (−5): faults and moving plates; they need a hot interior, a big enough planet and liquid water", "`thick_air` (−3) / `thin_air` (−4): air of 2 bar or more, or under 0.3 bar", "`subsurface_ocean` (−4): an ocean under the ice, warmed from below", "`acid` (−5): eats away: stone into hollowed ground, iron into rust, water into bitter water, coral into salt"] },
  ] },
  { id: "phys", part: "write", icon: "atom", title: "Physics values", check: "phys", body: [
    { p: "Optional lines that set the planet's numbers. Leave them out and the world draws plausible ones from its seed. Write `key: number` (or `key = number`); a comma works as a decimal point (`1,5`). A unit word after the number is allowed but ignored (`1 bar`), except `Ma` for the age (`age: 500 Ma`) and `d` or `days` for the rotation (`rotation: 3 d`). French keys work with or without accents (`marées:` or `marees:`). The Details tab (Physics of the world) shows the values the world ended up with." },
    { code: "```age\nsingle_sun\nwater\nmass: 1.2\nage: 3.5\natmosphere: 1.5\ncore: liquid\n```" },
    { table: { phys: true, head: ["Line (other spellings)", "Typical value", "What it is, how it is measured"], rows: [
      ["`mass:` (`masse:`)", "`mass: 1`", "The planet's mass, in Earths (Earth 1, Mars 0.11, a super-Earth 3 to 8). More mass: stronger gravity, and a planet that keeps its air and its inner heat longer. From 0.01 to 20."],
      ["`radius:` (`rayon:`)", "`radius: 1`", "The planet's radius, in Earth radii (Earth 1, about 6,400 km; Mars 0.53). Usually left out: it follows from the mass and the iron share. From 0.05 to 4."],
      ["`age:` (`âge:`)", "`age: 4.5`", "Time since the world formed, in billions of years (Earth 4.5); `age: 500 Ma` is 500 million years. A young world is hot inside (volcanoes); simple life needs at least 0.3, trees and animals at least 1. At most 13.8."],
      ["`orbit:` (`orbite:`, `distance:`)", "`orbit: 1`", "Distance from the star, in astronomical units: 1 AU is the Earth–Sun distance, about 150 million km (Mars 1.5). The light received then follows from the star's brightness, and `insolation:` is ignored. From 0.005 to 1000."],
      ["`insolation:` (`flux:`)", "`insolation: 1`", "How much starlight reaches the planet, compared with Earth (Earth 1, Venus 1.9, Mars 0.43). It sets the temperature more than anything else. Liquid water is easiest between about 0.36 and 1.1 (the habitable zone)."],
      ["`star_mass:` (`masse_étoile:`)", "`star_mass: 1`", "Mass of the star, in Suns. Lighter stars are redder, dimmer and almost eternal (`star_mass: 0.3` is a red dwarf); heavier ones are whiter, brighter and die young (at 2 Suns, after about 1.3 billion years). From 0.08 to 60."],
      ["`rotation:` (`spin:`)", "`rotation: 24`", "Length of the day in hours: the time the planet takes to turn once on itself (Earth 24). `rotation: 3 d` is three Earth days. A slow spin weakens the magnetic field. Ignored with `frozen_cycle`."],
      ["`core:` (`noyau:`)", "`core: liquid`", "The metal heart of the planet. In words: `liquid` (or `liquide`), `solid` (or `figé`), `none` (or `aucun`). As a number from 0 to 0.8: the share of the planet's mass that is iron core (Earth 0.33). A liquid core that turns fast makes a magnetic field, which shields the air and feeds auroras."],
      ["`atmosphere:` (`atmosphère:`, `pressure:`, `pression:`)", "`atmosphere: 1`", "Air pressure at the ground, in bars (Earth 1 at sea level, Mars 0.006, Venus 92). In words: `none` (under 0.01), `thin` (0.005 to 0.5), `dense` (3 or more); also `aucune`, `mince`, `épaisse`. Under 0.006 bar, water cannot stay liquid. A number here replaces what `volatiles:` would give."],
      ["`water:` (`eau:`)", "`water: 1`", "How much water the planet holds, compared with Earth's oceans (Earth about 1). It is an amount, not a state: temperature and pressure decide whether it is sea, ice or vapour. Without this line it is 0.3, and some blocks change it: 1 with `water`, 3 with `ocean_world`, 0.02 with `desert_world`. From 0 to 10."],
      ["`volatiles:`", "`volatiles: 1`", "The stock of gases (carbon dioxide, nitrogen, water vapour) that the rock can breathe out through volcanoes to build the air, compared with Earth (drawn between 0.1 and 5). It cannot be measured directly: it is estimated from what a planet is made of. Here, air pressure is roughly volatiles × volcanic activity × the share the planet can hold on to (gravity, magnetic field). Raise it for thicker air without fixing the pressure. From 0 to 10."],
      ["`albedo:` (`albédo:`)", "`albedo: 0.3`", "The share of starlight bounced straight back to space, from 0 (black) to 1 (a mirror). Earth 0.3, the Moon 0.12, fresh snow about 0.8, the clouds of Venus 0.77. A brighter world stays cooler. Values above 0.9 count as 0.9."],
      ["`tides:` (`marées:`)", "`tides: 0.03`", "Heat made inside the planet by tides, counted in units of Earth's whole inner heat (Earth's inner heat = 1). A nearby moon, giant planet or star stretches and squeezes the rock at every turn, and the friction warms it, like putty kneaded in the hand. It is not the height of sea tides. Without this line: 0, 0.03 with `companion_moon`, 0.1 to 5 for the moon of a giant (`planet_rings`), a little more for a world very close to its star. From 0 to 50."],
      ["`tilt:` (`inclinaison:`, `obliquity:`, `obliquité:`)", "`tilt: 23`", "How far the spin axis leans from the orbit, in degrees: this is what makes the seasons. At 0°, the sun follows the same path all year; at 23° (Earth), marked seasons at middle latitudes; at 60° and more, scorching summers and winters of night. The sheet derives the gap between summer and winter, smoothed by thick air and by the sea, exaggerated by thin air. A world whose spin the tide has frozen has no seasons, whatever is written; an erratic cycle (`erratic_cycle`) wants an axis that tips over. Without this line: drawn moderate, between 0 and 45°. From 0 to 90."],
    ] } },
    { p: "Numbers fix a value; words (`core: liquid`, `atmosphere: thin`) are claims that the physics checks without fixing anything (except `core: none`, which sets a planet with almost no iron). A number out of range is brought back into it, and the sheet says so; 0 is ignored where it means nothing (mass, radius, age, orbit, insolation, star mass, rotation)." },
    { p: "Earth, for scale: `mass: 1`, `age: 4.5`, `orbit: 1`, `star_mass: 1`, `rotation: 24`, `core: 0.33`, `atmosphere: 1`, `water: 1`, `volatiles: 1`, `albedo: 0.3`. Mars: `mass: 0.11`, `insolation: 0.43`, `atmosphere: 0.006`, `water: 0.3`, `albedo: 0.25`." },
  ] },
  { id: "amounts", part: "write", icon: "gauge", title: "Quantities", body: [
    {"p": "A quantity line makes something already written more or less present. It creates nothing: `many: gold` with no `gold` line does nothing."},
    {"code": "```age\ngreat_tree\nrain\ngold\nmany: trees, gold\nfew: rain\n```"},
    {"h": "How to write it"},
    {"ul": ["Two ways, same meaning: the quantity first (`few: rain`) or the block first (`rain: few`)", "The words: `many` (also `much`, `lots`, `plenty`, `beaucoup`), `few` (also `little`, `peu`), and `normal`, which cancels a quantity", "Several targets on one line, separated by commas: `many: ruins, trees, gold`", "A target is a **group** (table below) or **any block** written in the Age (`few: great_tree`)", "Two lines on the same target: the last one wins"]},
    {"h": "What it does"},
    {"ul": ["**Stability**: `many` makes a block cost twice its weight, `few` 40% of it. Blocks that give points back (`companion_moon`…) are left as they are. Riches follow the same rule, and so do the scars that give part of their cost back (see “Riches and scars”)", "**The generative window**: how much of it is drawn (last column below)", "**Dosing**: the quantity also sets how hard a clash between sky and matter bites (see “Dosing, rigour and depth”)"]},
    {"h": "Groups"},
    {"table": {"head": ["Group (French name)", "Covers", "In the generative window"], "rows": [["`ruins` (`ruines`)", "`door`, `sealed_door`, `bridge`, `fallen_bridge`, `tablet`, `worn_tablet`, `speaking_tablet`, `lamp`, `lit_lamp`", "How many ruins stand (up to 7)"], ["`trees` (`arbres`)", "`grove`, `great_tree`, `ironwood`, `charred_grove`", "How many trees (1 to 10)"], ["`water` (`eau`)", "`water`, `brine`, `meltwater`", "How many ripples on the water"], ["`rain` (`pluie`)", "`rain`, `storm`, `thunderstorm`, `whispering_storm`, `waiting_thunder`, `drizzle`", "How dense the drops are"], ["`fog` (`brume`)", "`fog`, `marsh_mist`, `rime`, `watching_mist`", "How thick the fog is"], ["`wind` (`vent`)", "`wind`, `dust_storm`, `ash_cloud`, `spore_cloud`", "How many motes the wind carries"], ["`moths` (`papillons`)", "`moth`, `lantern_moths`, `whispering_moths`", "How many small lights drift"], ["`glow` (`lueurs`)", "`glowvine`, `wrong_glowvine`", "How many small lights drift"], ["`riches` (`richesses`)", "All the riches (`gold`, `silver`, `gems`, `rare_ore`, `pearls`, `copper`)", "How many glints in the rock"], ["`scars` (`cicatrices`)", "The six scars", "Nothing: stability only"], ["`clouds` (`nuages`)", "No block", "How many clouds (window only)"], ["`stars` (`étoiles`)", "No block", "How many stars; with `few`, no band of stars and no nebula (window only)"]]}},
    {"p": "`rain: few` and `few: rain` are the same line. For the weather that comes and goes (how often, at which hours), see “Weather lines”."},
  ] },
  { id: "book", part: "write", icon: "book-open", title: "Links, seed, state of the book", body: [
    { code: "```age\nreturn: [[Hub]]\nlink: [[Sunder Reach]]\nlink: [[Glass Marsh]]\nseed: 1118\ncover: sober\n```" },
    { ul: [
      "`link: [[Note]]`: a linking book to another Age; one line per book",
      "`return: [[Note]]`: the return book, the way home",
      "`panel: [[image.gif]]`: your own image in the linking panel, instead of the painted one",
      "`seed: 42`: any text or number; it changes the draw (same note + same seed = same world)",
      "`cover: sober`: the cover's sobriety: `ornate`, `classic`, `sober`, `plain`, or a number from 0 (ornate) to 1 (bare); also `couverture:`, `cover_style:`, `sobriety:`"] },
    { h: "A trap or a damaged book" },
    { code: "```age\nwater\ntrap book\ndamaged_pages = 2\nremoved_pages = 1\n```" },
    { ul: [
      "`trap book` alone on its line (also `trap_book`, `livre piège`, `trap: yes`): no return, no fissure; `trap: no` says it is not a trap",
      "`damaged_pages = 2`: damaged pages (a whole number; `:` works too)",
      "`removed_pages = 1`: torn-out pages (also `torn_pages`)"] },
    { p: "What these do to the link is in “Traps, damaged books, links”." },
  ] },
  { id: "weatherlines", part: "write", icon: "cloud-drizzle", title: "Weather lines", body: [
    { p: "**Living weather.** A weather line can say how often and when: `drizzle: often, dawn`." },
    { ul: ["How often: `always`, `often`, `sometimes`, `rarely` (French: `toujours`, `souvent`, `parfois`, `rarement`), a fraction (`1/10`) or a percentage (`30%`)", "When: `dawn`, `morning`, `noon`, `afternoon`, `dusk`, `night` (French: `aube`, `matin`, `midi`, `après-midi`, `soir`, `nuit`), one or several; none = any time"] },
    { p: "The draw depends on the Age's seed and the day: same Age, same day, same weather for everyone. A bare `rain` line still means rain all the time." },
    { p: "Only the generative window follows the hours; the description gains a sentence (“At dawn, more often than not, a fine drizzle falls.”)." },
    { code: "```age\ndrizzle: often, dawn\nrainbow: sometimes, afternoon\nsnow: rarely, night\nfog: 1/10, night\n```" },
  ] },
  { id: "winlines", part: "write", icon: "app-window", title: "Window lines", body: [
    { p: "Lines that change only how the linking window looks. Without them, the settings decide." },
    { code: "```age\nwindow_style: generative\nwindow_size: xl\nfx: ripple\nday_length: 40\nyear_length: 12\nmoons: 2\n```" },
    { ul: [
      "`window_style: generative` or `classic`: a landscape drawn from the seed, or the engine's painted window; also `render:`",
      "`window_size: large`: `normal`, `large` or `xl`; or `window_width: 520`, a width in pixels from 200 to 800",
      "`fx: tv`: the window effect: `classic`, `static`, `ripple`, `sweep`, `tv`, `random`, `off`; also `window_fx:`, `link_fx:` (colon only)",
      "`day_length: 40`: real minutes per day of the Age, from 0.2 to 1440; the sun follows your computer's clock (generative window); also `day:`",
      "`year_length: 12`: days per year, from 1 to 365; the sun's height follows the seasons; needs `day_length`; also `year:`, `revolution:`",
      "`moons: 2`: moons drawn in the sky, from 0 to 5 (generative window); also `lunes:`; without it, `companion_moon` gives one"] },
  ] },
  { id: "mechlines", part: "write", icon: "cog", title: "Mechanisms", body: [
    { p: "Abandoned machines with a puzzle, shown in the Details tab. A line names one or several (colon only); spaces and capitals are forgiven (“Water Valve” works)." },
    { code: "```age\nmechanism: water_valve, telescope\n```" },
    { ul: [
      "Mechanisms: `steam_powered_elevator`, `water_valve`, `telescope`, `sound_lock`, `frequency_array`, `steam_generator`, `holofatic_imager`, `orrery`, `tide_gate`, `wind_organ`, `lens_array`",
      "Other keys: `dnie_mechanism:`, `puzzle_type:`, `puzzle:`",
      "An unknown name is flagged in the Details tab. With the setting “Mechanisms: draw”, the Age may also invent one or two"] },
  ] },
  { id: "lib", part: "write", icon: "library", title: "Your own blocks (age-library)", body: [
    { p: "A code block of type `age-library`, in any note, adds your own blocks, reactions and variants. One definition per line:" },
    { code: "```age-library\nblock moonmilk: pale, thick, patient | geological\nproduct curd: soft, white, sour | geological\nreaction moonmilk + salt -> curd (soothing)\nvariant curd -> watching_curd with crystal\n```" },
    { ul: [
      "`block id: three, adjectives | axis`: a block you can write in an `age` block; optionally `weight=0.03` after the axis",
      "`product id: … | axis`: a product (born of a reaction, never written); optionally `bonus=-0.1`",
      "`reaction a + b -> product (type)`: types `violent`, `corrosive`, `crystallizing`, `soothing`, `transmuting`, `growing`, `feeding`, `decaying`, `awakening`",
      "`variant product -> rare_product with catalyst`: without `with`, the catalyst is `strange_stone`",
      "Axes: `cosmological`, `geological`, `metaphysical`, `weather`, `ecological`"] },
    { p: "Reusing a built-in identifier replaces it. In reading view the block shows its errors line by line. Library blocks are never drawn at random; the window paints them from their axis and adjectives. Commands: create a library note, copy the built-in content, reload the library." },
  ] },

  // ---- Ce que l'Âge produit seul ---------------------------------------------------------------------------------
  { id: "stab", part: "gen", icon: "activity", title: "Stability and the draw", body: [
    { p: "Five axes: cosmological, geological, weather, ecological, metaphysical (plus `alteration`, from the law of change). Every block, clash and ink blot costs points on its axis. The Age takes the stability of its weakest axis: **75% or more: stable**, **40 to 74%: unstable**, **under 40%: dying**." },
    { h: "What the Age draws when you leave it open" },
    { ul: [
      "Eleven slots: stars, day cycle, moon, phenomena, ground, minerals, weather, flora, fauna, ruins, fissure. Stars, day cycle, ground and fissure take one value: write one and nothing else is drawn there (`twin_suns` means no drawn sun). The other slots can still add to what you wrote",
      "Same note + same `seed:` → same world. Renaming the note keeps its world and its star: the plugin writes its former name as the property `age_seed` (delete it to draw a new world). For an Age renamed before that existed: command *Give this Age back the world of its former name*",
      "Ordinary values come up more often; what would clash or react violently is less likely, never impossible (engine setting “How much a clash steers the draw”)",
      "Drawn pages are marked in the book, and in the stability details where they cost something (\"What does not hold\"). ✓ keeps one as written. A drawn page is never in your YAML: to close a box, write its value. Stars, cycle, ground and fissure take one value, so writing one is enough, and the details offer the other values as one-click buttons",
      "A light clash that touches a drawn page costs nothing; a bigger one leaves a scar instead of its full price (see “Scars the world keeps from its draw” under matter blocks)",
      "The “Solitude” setting weights the draw toward deserted worlds: more ruins and wild nature, fewer hunters",
      "Orbit, sun colours, world types, terrain, riches, scars and all the other blocks marked “never drawn” only exist if you write them"] },
    { h: "Mutation" },
    { p: "An Age that stays unstable (under 75 %) is not always frozen: some Ages, not all (about one in three, decided by their name), can mutate. For them, after a few days, two elements that contradict each other may bind themselves together (a **symbiosis**); it is never certain: two months on average, sooner when a fissure is eating the Age (the world defends itself). When it can, the union picks a pair from which one of Wonders may grow. The union supports the world on the axis of its contradiction (15 points at most for the whole Age, each further union counts half as much, four at most) and never lowers stability. It holds as long as both elements are there; remove one and it falls, put it back and it resumes. Nothing wears out with time. A stable Age does not mutate, except, very rarely, once. Unions are listed under stability, in the Details tab. To try it without waiting: the command “Mutation: advance four days on the open Age (test)”, which forces the union even on an Age that cannot mutate." },
    { h: "Wonders" },
    { p: "Some unions give birth to a **wonder**, something that obeys another law: breathing mirrors (water + lava), the visiting weight (heavy world × light world), the rings (jungle world × desert world), the mosaic (sick flowers), the day aurora (auroras × ash cloud)… seventeen in all, none of them written. The window draws it, the description tells it, and it leaves if the union falls. Other wonders grow from a pair you write: petal rain, scented mist, the living mist (fog + spores)…" },
    { p: "**The chamber of memories**: every wonder seen once floats in a glass orb, with its living window. You enter through the orb floating near the lounge ceiling (turn around in the cabin). Clicking an orb makes it chime and offers to let it go; a wonder still alive will come back when you see it again. A deleted Age leaves its orb, paler: a world that is no more. The command “Empty the chamber of memories” clears everything." },
    { p: "**The harvest**: some Ages give, once a day when you read them, a measure of what the machine needs: **ash**, **humus** (`humus`), **silt** (born of water on ash, or on stone and sand) and **peat** — only if they are written (or born of what is written) and something grows there. A matter has its **genesis**, decided by the Age: ash is **volcanic** in a world of lava, **from a hearth** in a world that burns (with neither, it stays poor); silt is **volcanic** in a world of lava, **of quartz** otherwise. One more measure when the season favours the matter, one more when the written amount is strong (`many: ash`). The Details tab says what the Age gave today. The first harvest raises a lean-to against the cabin; the harvest goes down to its **cellar**, stored by season: there you sieve the good grain from the poor (the poor goes to the compost, which makes potting soil of it), and send your jars up to the hoppers." },
    { p: "**The machine**, in the lean-to: four glass hoppers (you see what is in them), a mixing column (a click on a hopper drops one measure in it; five at most; a click on the column pours it back), two bare sliders (time and temperature, 0 to 50), and the press, with its gauge (how dense the pellet will be). Close the door: the column empties into the oven, and the batch cooks in real time (one notch of time is fifteen seconds); the pellets then wait on the five-hollow tray. One measure, one pellet. Precise settings: click above or below a slider, or right or left of the wheel, for one notch (Shift: five); drag; the mouse wheel; the value shows in the tooltip. The recipes are not written anywhere: you learn them by failing. A failed batch: the lever to the right of the tray drains it through the grate, past the shelf. A pellet you don't want: click its pile and it goes into the fire (not while cooking; each kind has its own smoke: pale, amber, and green for grey). You can also reach it from inside: in the main room or the lounge, the bottom of the view **steps back into the hallway**, with the forge door at its end (bricked up until the lean-to exists)." },
    { p: "**The cave**: in the cellar (the crypt, in the Castle), a crack leads under the island: a hole in the floor, a niche where the pellets go, a stone to press. A pellet falls for a minute; you have to be down by the water before it arrives." },
    { p: "**The microscope**, on the writing-room desk, left of the lamp (once the machine exists): click the pool in the cave to fill its flask with the water of the day; the eyepiece shows what lives in it, without a number. Three dishes drop a crumb of pellet into it, without spending the pellet: you see what it would do to the lake. Test command: \"Cave: tests\" (wrench menu)." },
    { h: "Home" },
    { p: "No return book **and** no fissure: the Age is a trap. With water, a drawn fissure lies underwater." },
    { p: "Stability is recalculated each time an Age is read, with the rules in force. When the rules evolve, an existing Age may gain or lose a few points, mostly at higher rigours; at the default gentle rigour little changes. Its text, pages and draw never change." },
    { p: "How the costs are weighed (dosing, rigour, depth) has its own topic, “Dosing, rigour and depth”; the title an Age can earn is in “Writer's title”." },
  ] },
  { id: "dosing", part: "gen", icon: "scale", title: "Dosing, rigour and depth", body: [
    {"p": "Beyond the price of each block, three layers weigh what you wrote. The panel shows what they changed on one line under the costs, then one sentence on how deeply the Age rests."},
    {"h": "1 · The extent of a clash"},
    {"p": "A clash between the sky and the matter costs in proportion to how much they touch, not all or nothing: the quantity (`few:` 0.4, normal 1, `many:` 2) × the size of the world × the number of biomes. `few: water` in a desert world is a pond, not a lake: it clashes less. Below 1 the clash is softened, above 1 it is made worse."},
    {"ul": ["The size of the world: the line `size: small | medium | large` (0.6 · 1 · 1.5; medium if absent). Not to be confused with `window_size`, which is the window", "Each biome written beyond the first (list below) adds 15%"]},
    {"h": "Biomes"},
    {"p": "A biome is a family of ground. Write one block of a family and the Age has that biome; the number of biomes is the number of different families written (at least 1). Each biome beyond the first adds 15% to the extent of every clash. A world type is the dominant biome, and every other family adds one. Nothing here is ever shown as a globe."},
    {"table": {"head": ["Biome", "Blocks that make it"], "rows": [["Desert", "`sand`, `desert_world`, `scorched_surface`"], ["Ice", "`deep_cold`, `snow`, `frozen_world`"], ["Water", "`water`, `ocean_world`, `kelp`, `coral`, `subsurface_ocean`, `bitter_water`, `submarine_fissure`, `river`, `delta`, `lake`, `marsh`"], ["Fire", "`lava`, `lava_world`, `molten_core`, `geysers`, `ash`"], ["Stone", "`stone`, `iron`, `crystal`, `strange_stone`, `hollowed_ground`, `mountains`, `canyon`, `cavern_world`"], ["Forest", "`great_tree`, `vine`, `fern`, `grass`, `flowers`, `garden`, `jungle_world`"], ["Salt", "`salt`"]]}},
    {"p": "Two blocks of the same family count once (`sand` and `scorched_surface` are one biome). Where two biomes oppose each other (water and lava, ice and desert), the clash itself costs what the contradiction table already says; the number of biomes only weighs it."},
    {"h": "2 · Weather that follows from itself, and the budget"},
    {"ul": ["Weather that follows from itself (rain and wind making a storm, a storm and lightning making thunder) is not held against the Age", "From balanced rigour up, everything has a budget: beyond the capacity of an axis, each thing written adds a little more than the last"]},
    {"h": "Coherence buys capacity"},
    {"p": "Every axis can carry six things for free. Each law of that axis that your Age brings into play **and** keeps adds two, up to sixteen. A law only counts if it applies: a world without a great tree gains nothing from “the ground bears the tree”. And nothing is free: what makes a law hold has to be written, and costs its own points. A rich world that holds together can stay stable at every rigour; a world with a lot of everything still cannot."},
    {"table": {"head": ["Axis", "Laws that buy capacity (+2 each)"], "rows": [["Ecological", "the loop of life and death closes (a decomposer or a scavenger); the large rests on the small (micro-life, water, mould); the flowers have a pollinator; plankton has light, the microbial mat has heat or chemistry; the pellet is not overdosed"], ["Geological", "the ground bears the great tree written on it"], ["Weather", "the weather follows from itself (rain and wind make a storm)"], ["Cosmological", "the sky agrees with itself: at least two sky blocks written and no clash on the sky axis between pages you wrote"], ["Metaphysical", "none yet"]]}},
    {"p": "Take away what keeps a law and the capacity falls with it: that is why a rich, coherent Age often rests **held** or **by a thread** rather than deep."},
    {"h": "3 · How deeply the Age rests"},
    {"p": "Each line is removed in turn. If the Age falls without one of them, it holds **by a thread**; otherwise it holds, or **rests deep**. Nothing is said of an Age that is not stable. No number is shown."},
    {"p": "Depth also weighs on retouching (the law of change): once the ink has dried, changing an Age that rested deep costs less, changing one that held by a thread costs more. The notice says so. This follows the *balance* family of the rigour: nothing changes at gentle rigour."},
    {"h": "Rigour of the laws (setting)"},
    {"p": "The setting decides how much of all this counts against stability."},
    {"table": {"head": ["Level", "What counts"], "rows": [["Gentle (default)", "Nothing new costs stability: only what lightens an Age counts (a little water in a desert, a storm that follows from itself)."], ["Balanced", "What makes a clash worse counts at half."], ["Strict", "In full, on the families of laws you tick: physics, soil, life, extent and dosage, balance. The others count at half."], ["Extreme", "Everything counts, in full."]]}},
    {"p": "The five families all act: physics, soil, life, extent and dosage (with the budget), and balance (the cost of retouching, by depth). The laws of life and soil are described with the matter blocks (“Matter blocks”). The rigour you held also decides which writer's title an Age can earn (see “Writer's title”)."},
    {"h": "Reading the world (setting)"},
    {"p": "An Age is known by reading it. A light fault (a sickness of the living, a light scar from the draw) costs its points from the first reading, but the world names its cause only with time: first a sign (only the family: “a tension in the living”), then a symptom (what can be seen: “the green yellows in patches”), then the cause, with the block. Strong faults are always said at once. The window and the book always show everything: only the words mature."},
    {"table": {"head": ["Rigour", "Symptom after", "Cause after"], "rows": [["Gentle", "at once", "at once"], ["Balanced", "1 day", "3 days"], ["Strict", "2 days", "7 days"], ["Extreme", "3 days", "14 days"]]}},
    {"p": "The clock starts when the fault appears, not when you look. A Master skips the sign; a Grand Master sees the cause with the symptom. The setting “Reading the world” makes it slow (twice as long), normal, or immediate. A fault that goes away is forgotten; if it comes back, the clock starts again."},
  ] },
  { id: "title", part: "gen", icon: "award", title: "Writer's title", body: [
    {"p": "Writing earns a title. It recognises what you have achieved and never locks anything: every block, line and room stays open to everyone."},
    {"p": "An Age that stays **stable** (75% or more) for **seven days in a row**, under a given rigour, raises your title to the step that rigour gives:"},
    {"table": {"head": ["Title", "Earned with…", "What the ledger reads (see “Write an Age from the Relto”)"], "rows": [["Apprentice", "(where everyone starts)", "The description, the verdict in words, the glyphs it recognises, and one alert: the gravest"], ["Scribe", "Gentle rigour", "All the alerts, and the lines it does not understand"], ["Seasoned Seltahn", "Balanced rigour (or Strict with fewer than three families ticked)", "And the dosing in words, and how deeply the Age rests"], ["Master", "Strict rigour, with at least three families ticked", "And the family of each alert, the extent, the load, the reactions and their ingredients"], ["Grand Master", "Extreme rigour", "Everything, with the costs per axis in points"]]}},
    {"ul": ["The title is **global**: the highest step reached, whichever Age earned it. It never goes back down", "The first Age to hold seven days is also marked once", "Changing the rigour (or, in strict, the ticked families), or falling below stable, restarts the count", "The days are real elapsed days (the clock), not the number of times you open the Age"]},
  ] },
  { id: "react", part: "gen", icon: "flask-conical", title: "Reactions (never written)", check: "products", body: [
    { p: "When two blocks of the Age meet, they can react and add a product to the world. Products appear by themselves in the description and in the book, and can react in turn." },
    { note: "Never write a product: it is not a block, and alone on its line it is an ink blot. Write its ingredients instead (`water` and `lava` give `obsidian`)." },
    { h: "Geology" },
    { ul: ["`obsidian` ← `water` + `lava`", "`ice` ← `water` + `deep_cold`", "`glass` ← `sand` + `lava`", "`rust` ← `water` + `iron`, or `acid` + `iron`", "`brine` ← `water` + `salt`", "`silt` ← `water` + `ash`", "`diamond` ← `ash` + `pressure`", "`humming_shard` ← `crystal` + `strange_stone`", "`crying_obsidian` ← `salt` + `obsidian`", "`fulgurite` ← `lightning` + `sand`"] },
    { h: "Weather" },
    { ul: ["`storm` ← `rain` + `wind`", "`thunderstorm` ← `storm` + `lightning`", "`marsh_mist` ← `fog` + `water`", "`dust_storm` ← `wind` + `sand`", "`ash_cloud` ← `wind` + `ash`", "`hail` ← `rain` + `deep_cold`", "`steam` ← `rain` + `lava`, or `heat` + `water`", "`rime` ← `fog` + `deep_cold`", "`meltwater` ← `heat` + `ice`", "`spore_cloud` ← `wind` + `spore`", "`charged_crystal` ← `lightning` + `crystal`", "`scented_mist` ← `fog` + `flowers`", "`petal_rain` ← `wind` + `flowers`", "`glaze` ← `drizzle` + `deep_cold`", "`crystal_rain` ← `drizzle` + `crystal`", "`ash_rain` ← `drizzle` + `ash`", "`acid_rain` ← `drizzle` + `acid`", "`meltwater` and `steam` also come from `snow` + `heat` and `snow` + `lava`"] },
    { h: "Life" },
    { ul: ["`moss` ← `spore` + `water`", "`scorched_moths` ← `moth` + `heat`", "`tarnished_growth` ← `gold`, `silver` or `copper` + `great_tree`, `fern`, `flowers`, `grass` or `vine`", "`living_mist` ← `fog` + `spore`", "`lichen` ← `moss` + `deep_cold`", "`pale_fungus` ← `spore` + `ash`", "`mushroom` ← `mycelium` + `water`", "`aeroplankton` ← `spore_cloud` + `fog`", "`soil_bacteria` ← `spore` + `silt`", "`humming_blooms` ← `bee` + `flowers`", "`sapling` ← `seed` + `water`", "`meadow` ← `grass` + `flowers`", "`ironwood` ← `sapling` + `pressure`", "`cinderbloom` ← `seed` + `lava`", "`glowvine` ← `vine` + `crystal`", "`withered_fern` ← `fern` + `salt`, or `heat` + `fern`", "`charred_grove` ← `great_tree` + `lava`", "`grove` ← `great_tree` + `water`", "`wildfire` ← `lightning` + `great_tree`", "`lantern_moths` ← `moth` + `glowvine`", "`herd` ← `grazer` + `moss`", "`stalking_pack` ← `hunter` + `herd`", "`warren` ← `burrower` + `silt`", "`still_drifter` ← `drifter` + `deep_cold`"] },
    { h: "Ruins" },
    { ul: ["`worn_tablet` ← `tablet` + `water`", "`lit_lamp` ← `lamp` + `crystal`", "`sealed_door` ← `door` + `pressure`", "`blurred_book` ← `book` + `water`", "`fallen_bridge` ← `bridge` + `rust`", "`speaking_tablet` ← `tablet` + `strange_stone`"] },
    { p: "Violent reactions cost the most (up to 25 points); soothing, growing and crystallizing ones give a few points back. `acid` also turns `coral` into `salt`, `stone` into `hollowed_ground` and `water` into `bitter_water` (blocks that can also be written)." },
    { h: "Rare variants (with strange_stone)" },
    { p: "When `strange_stone` is in the Age, these products show as their rare variant:" },
    { ul: ["`whispering_obsidian`, `black_ice`, `singing_glass`, `living_rust`, `clouded_diamond`", "`whispering_storm`, `waiting_thunder`, `watching_mist`, `black_hail`", "`singing_lichen`, `wrong_glowvine`, `whispering_moths`, `watching_herd`, `humming_warren`", "`glowing_mushroom` (with `strange_stone`) and `singing_mushroom` (with a `crystal`): the two rare variants of the mushroom"] },
  ] },
  { id: "physgen", part: "gen", icon: "orbit", title: "Physics of the world", body: [
    { p: "Beneath the blocks lies a small physical world: star, orbit, planet, inner heat, core, magnetic field, air, temperature, water, light. It is not a simulation: simplified laws, tuned so that Earth, Mars, Venus and the Moon come out roughly right. What the book leaves open is drawn from the seed, under constraints: the world looks for a physics that holds what you wrote (48 attempts, always the same for the same seed)." },
    { p: "The Details tab shows the result as a sheet. When something does not hold, it says why and proposes a line to write (`age: 3.5`); one click writes it into the block." },
    { h: "Modes (Settings › Ages & mechanics)" },
    { ul: ["**Easy** (default): the sheet explains, stability never changes. World types (`frozen_world`…) steer the draw", "**Strict**: each tension costs on its axis (light 10, medium 20, heavy 35 points, at most 45 per axis), multiplied by the “Physics severity” slider (0.5 to 2). World types no longer steer the draw: they are only checked", "**Off**: nothing"] },
    { h: "Builders" },
    { p: "Ruins (`tablet`, `door`, `bridge`, `lamp`, `book`, `library`, `garden`…) say that someone passed through: they may have brought what nature could not have made in time. They do not excuse impossible life. The Relto is outside physics: it is the safe zone." },
  ] },
  { id: "window", part: "gen", icon: "image", title: "What the window shows", body: [
    { p: "**Rendering**: `classic` (the engine's painted window) or `generative` (a landscape drawn from the seed: tinted sky, relief, vegetation, weather, reflections, foreground, one inhabited detail per Age). Unknown blocks are painted from their axis and adjectives." },
    { p: "In the generative window nothing is decorative: everything comes from the book and its physics." },
    { ul: ["**Shores**: water and land in the same Age share the bottom of the image; the shore follows what is written: lava (a black, smoking coast), sand (beach and dunes), ice (pack ice), stone or ruins (rocks), plants (a grassy bank). World types impose their own scenery and have no shore", "**Foreground**: rocks, branch, arch, vines, reeds, leaves, pillar, ice stalactites, or nothing; drawn according to the Age (reeds only near water, ice only if it freezes). Branches grow differently each time (burnt, snowy, mossy, flowering, needles…)", "**Visible physics**: the colour and size of the sun come from the star and the distance; thin air darkens the sky (stars in daylight, few clouds), thick air makes it milky; strong gravity flattens the relief, weak gravity raises it; a frozen face keeps the sun still; a cold or burning world shows", "**Nights**: each Age has its own sky: two to four constellations, sometimes a nebula or a band of stars, its moons (`moons:`); `few: stars` is respected", "**Below the surface**: `kelp`, `coral` and `acid` show in the water, in their place"] },
    { p: "**Effects** (`fx:` or setting): `classic` (tremors, shifting sky, fractures according to instability), `static` (snow), `ripple`, `sweep`, `tv` (old television), `random` (one effect per Age name), `off`. Intensity from 0.2 to 2; `prefers-reduced-motion` is respected." },
    { p: "**Damage** (drawn from the book's seed): `damaged_pages` = shifted zones, red/cyan split, frozen zones or ink blots; `removed_pages` = burnt holes with snow; strong instability = branching fractures. Up to 12 zones and 6 holes; `fx: off` removes them." },
  ] },
  { id: "trap", part: "gen", icon: "triangle-alert", title: "Traps, damaged books, links", body: [
    { ul: ["**Trap book** (`trap book`): no return (a `return:` line is ignored) and no fissure; it looks perfectly normal", "**Damaged book**: each `damaged_pages` adds 0.08 of linking instability, each `removed_pages` 0.15 (at most 0.9). It affects only the link, not the Age's stability. From 0.3, “Listen to the static” appears", "**Unreliable links** (setting): beyond 30% linking instability, “open ↗” or a click on the window may waver (it fails, try again) or slip (you land in another book of the same Age). At 85%: 35% waver and 24% stray"] },
  ] },
  { id: "mech", part: "gen", icon: "puzzle", title: "Mechanisms and solitude", body: [
    { p: "Each mechanism has a state (dormant, rusted, overgrown, sealed, cracked) and a puzzle (pressure mark, order, angles or tones), whose values are given in D'ni numerals. With the setting “Mechanisms: draw”, the Age invents up to two, chosen by what it holds (water calls for valves, crystal for sound locks…)." },
    { p: "Solitude: off (the original draw), balanced (ruins ×2.2, flora ×1.3, hunters ×0.5), strong (ruins ×3.5, hunters ×0.25). Changing this setting changes the worlds drawn for open slots." },
  ] },
  { id: "journal", part: "gen", icon: "notebook-pen", title: "Journal, cover, properties", body: [
    { ul: ["**Journal**: the command “Create the exploration journal for this Age” creates a note with an `age-journal` block, written from the notes that point back to the Age. Voices inspired by characters from the games (English or French)", "**Cover**: a tab of the book, procedural (marble, leather, brass, glyphs, medallion), from the most ornate to the barest; SVG export", "**Map**: the command “Generate the Age map (canvas)” draws the linked Ages (blue = round trip, orange = one way)"] },
    { p: "Properties written into the note (commands “Update Age data…” or the automatic setting): `age_verdict`, `age_stability`, `age_axes`, `age_return`, `age_links`, `age_discovered`, `age_drawn`, `age_home`, usable with Dataview or Bases." },
  ] },
  { id: "snd2", part: "gen", icon: "volume-2", title: "Sounds", body: [
    { ul: ["**Book**: a dull thud, leather, pages (“Book sound”), then 2 to 5 clasp clicks (“Clasp clicks”)", "**Linking**: eleven variants (A to K) drawn at random, never the same twice in a row, with random pitch, glissando, tremolo, echo, chord", "**Page turn**: a synthesised paper rustle", "**Static**: breath with dropouts and a 50 Hz hum", "**Ambiences**: wind, pines, water, waterfall, rain, drone, metallic resonance, fire, crickets, thunder, pad, chime; minimal / zen / full levels", "**Safeguard**: the ambience stops if the note changes, if the tab closes or goes to the background; it keeps going when you switch tabs inside the Relto"] },
  ] },

  // ---- Relto ------------------------------------------------------------------------------------------------------
  { id: "relto2", part: "relto", icon: "mountain", title: "The refuge: note and block", body: [
    { p: "The command “Open the Relto” creates the refuge note (in the refuge folder) if needed. A `relto` code block shows the island in any note:" },
    { code: "```relto\ninscription: Shorah\ntime: 21.5\n```" },
    { h: "Options of the relto block (one per line, all optional)" },
    { ul: ["`source: [[Relto]]`: the refuge note (otherwise the first note with `age_type: personal_hub`)", "`time: 21.5`: a fixed hour (otherwise the computer's clock)", "`inscription: Shorah`: a motto under the image", "`dni_time: off`: hides the D'ni time", "`pages: hide`: no Pages tab, for a finished Relto (pages are then attached and detached in the book of pages, on the cabin table); without tabs, the page list starts collapsed", "`folders: Ages`, `exclude: Drafts`, `books: Sunder Reach, Glass Marsh`: which books stand on the shelf (comma-separated lists); otherwise the book pills of the Pages tab (filled = on the shelf), saved as `relto_books` in the note (`[]` = no books)"] },
    { h: "Wheels with a mouse" },
    { p: "Press a wheel and **turn around its centre**: at the hub a fine notch every 8°, at the rim a coarse one every 20°. In the large view and in full screen, the **scroll wheel** over a wheel turns it one fine notch (Shift: a coarse one); in a note, the scroll wheel scrolls the note. At the Imager, a glass is dragged along its rail, the iris lever along its arc. A click on ± still works." },
    { h: "On a phone or tablet" },
    { p: "The Relto is touched instead of hovered. The **first touch shows**: a frame and, under the picture, the sentence that says what it is. The **second acts**. A wheel you have read then acts at every touch, both halves and its hub. Passages (doors, books, going down) act at once. Touching empty space lets go. Put a finger on a wheel you have read and **turn around its centre**: at the hub a fine notch every 8°, at the rim a coarse one every 20° (the Imager's micrometer and knobs too). At the telescope, a touch on the eyepiece **magnifies** it; another gives it back. The full-screen button makes the Relto take all of Obsidian's room; held upright, the phone shows it lying a quarter turn: turn the phone to play. The book icon in the ribbon (the left menu) opens the Age Writer menu, whose first entry, the mountain, opens the Relto (the wrench icon: maintenance and tests); the book button in its bar opens this guide, on the topic of what you are looking at." },
    { h: "The refuge note (properties)" },
    { code: "---\nage_type: personal_hub\nage_name: Relto\nseed: 19991118\nenvironment:\n  base_terrain: volcanic_plateau\n  surrounding: cloud_sea\n  sky_cycle: system_time\nstructures: [hut, bookshelves, linking_pillars]\nrelto_pages_active: [page_pine_trees, page_waterfall]\n---" },
    { ul: ["`base_terrain`: volcanic_plateau, mossy_plateau, sand_island, glacier, obsidian_plateau", "`surrounding`: cloud_sea, fog_sea, ocean, void, lava_sea", "`sky_cycle`: system_time, frozen_dawn, frozen_day, frozen_dusk, frozen_night"] },
    { h: "D'ni time" },
    { p: "Computed from the computer's clock: year (hahr), month (vailee), day (yahr), then gahrtahvo : tahvo : gorahn : prorahn, in D'ni numerals. A prorahn lasts about 1.39 s." },
  ] },
  { id: "reltowrite", part: "relto", icon: "book-plus", title: "Write an Age from the Relto", body: [
    {"p": "You can write an Age without leaving the Relto. A **blank book** lies on the cabin table: click it to open it as a real book, in the middle of the screen."},
    {"h": "The book, page by page"},
    {"ul": ["**The linking window** comes first, once the Age exists. Click it: the linking sound plays and the note opens", "**Pages of glyphs**, drawn in ink on parchment, six to a page. An empty slot (+) opens the **binder**: leaf through it by family, click a glyph to write it. Glyphs you do not know yet are not offered. The × takes a glyph out", "**The description**: what the book says about the world, over two pages", "**The free page**: on the left, the lines already written (click one to bring it back to the draft, × to remove it); on the right, the writing page, one line per ruled line. Ctrl+Enter, or the small button, writes them. A line the engine does not understand is refused and stays in the draft", "To turn pages, click the edge of the page you want to go to"]},
    {"p": "The note is created with the first line you write (it is named “Age”: rename it as you like) and its linking book joins the shelf at once, unless the refuge's `folders` / `exclude` lines keep it off. What is typed but not yet written is lost if you close the book."},
    {"h": "One Age, one note, two books"},
    {"p": "An Age is a single note, and it has two books: the **descriptive** book (what you write) and the **linking** book (the way in, with its own look). Delete the note and both vanish. There is no delete button in the Relto."},
    {"h": "The vault"},
    {"p": "An iron hatch in the cabin floor, in front of the fireplace, leads down to a stone room: the vault of descriptive books. Each niche keeps up to five books, in alphabetical order, under a plaque that gives its range; twelve niches a page, and the arrows turn to the next page when there are more. Click a spine to reopen the book and correct it. The blank book stands on a lectern in the middle. Niches without a book hold small things of their own."},
    {"h": "The ledger"},
    {"p": "With the **Imager** page active, a small brass book lies beside the lectern, in the Imager's room. Set an Age's book on the lectern and open the ledger: it gives the **details of the Age**: its description, its verdict in words, the glyphs it recognises, then its alerts, its dosing, how deeply it rests, its reactions and, at the highest title, the costs in points. How much it tells grows with your writer's title (see “Writer's title”). In the Art of the Guild the lectern holds a blank book instead: the ledger appears once the world has formed on the page, and reads the Age you have found (never a world no one has written). The Details tab under the Age block is unchanged."},
  ] },
  { id: "reltopages", part: "relto", icon: "file-plus", title: "Relto pages", body: [
    { p: "Each page adds an element and an ambience to the island. Command “Create a Relto page” (or “New page” in the Pages tab) writes it as a note; attach it from the Pages tab." },
    { h: "Built-in pages" },
    { ul: ["`page_pine_trees`, `page_birches`, `page_palms`, `page_ferns`, `page_waterfall`, `page_fireflies`, `page_lanterns`, `page_snow`, `page_aurora`, `page_fireworks`, `page_mountain`, `page_pillars`, `page_chimney`, `page_mist`", "Under the island: `page_gems`, `page_gold`, `page_silver`", "Then: `page_rain`, `page_storm`, `page_birds`, `page_butterflies`, `page_moons`, `page_comets`, `page_dock`, `page_bench`, `page_islets`, `page_calendar`, `page_dni_clock`, `page_flowers`, `page_lily_of_the_valley`, `page_grass`, `page_ponderosa`, `page_maples`, `page_crystal_tree`, `page_stalk_tree`, `page_koi`, `page_pond_decor`, `page_cat`, `page_cat_toys` and `page_imager`"] },
    { h: "A page = a note" },
    { code: "---\nrelto_page_id: page_pine_trees\ntarget_age: Relto\nenabled: true\neffects:\n  canvas_additions:\n    - { type: vegetation, density: 0.7, asset: conifer }\n  ambiance_audio: wind_in_pines\nunlock:\n  age: \"[[Marais de verre]]\"\n  min_stability: 60\n  ages_count: 3\n---" },
    { ul: ["Effect types: vegetation, waterfall, fireflies, lanterns, snow, aurora, mist, fireworks, mountain, pillars, chimney, gems, gold, silver, koi, cat, rain, storm, birds, butterflies, moons, dock, bench, stalktree, cattoys, ponddecor, islets, calendar, flowers, grass, imager, telescope, dniclock, comet, glasshouse, castle", "Ambiences: wind, wind_in_pines, waterfall, river, soft_rain, night_crickets, deep_hum, fire_crackle, hearth, stone_choir, mountain_air, fireworks, metal_chimes, thunder"] },
    { p: "`castle` (page `page_castle`, the Castle, always in the sandbox book of pages, detached): a romantic gothic disguise. Outside, the whole island becomes the castle: the old mountain becomes its mass, bristling with gables and spires, set in the middle of the island and crowned by the keep (the observatory sits on the astronomer's tower), with a long crenellated range at its foot and a curtain wall across the courtyard; the rock becomes vaulted foundations under a low rampart, the cabin a small chapel of old mossy stone, the islets hanging towers joined by stone footbridges, the calendar pinnacle a granite stele with its number in gold, the waterfall a gargoyle; the grass, flowers, trees and the cat stay as they are. By day the sky stays the day's; at dusk it turns blood red, and at night a great red moon rises, bats cross it and a low crimson mist drifts under the island. Inside, dressed stone above dark walnut panelling, a parquet floor, pointed-arch doors and windows with red and violet stained glass, wrought iron, velvet and old gold, candles for light; every room, the Imager and the observatory included, takes on stone, walnut and gold. Only one disguise at a time: attaching the Castle detaches the Glasshouse, and the other way round. Nothing you click moves, except the observatory, which follows the keep to the middle of the island. Not in the story mode." },
    { p: "`glasshouse` (page `page_glasshouse`, the Glasshouse, always in the sandbox book of pages, detached): an art nouveau disguise for the whole Relto. The cabin becomes a pavilion of sea-green and amber glass under a copper dome, crowned by a small lantern the smoke rises from; inside, ogival stained glass with flower patterns, a mosaic floor, ornate rugs, lamps with leaded-glass shades whose light takes their colours; every room, the Imager and the observatory included, takes on copper and glass, and the D'ni clock stays open to the sky. Nothing you click moves. Not in the story mode." },
    { p: "`comet` (page `page_comets`): now and then a comet slowly crosses the sky, mostly at night; its density is how often it comes (about every 8 minutes at 0, about every minute at 1). Each pass lasts 40 to 60 seconds and depends only on the Relto seed and the time." },
    { p: "States: *active*, *available* (Attach button), *locked* (reason shown), *disabled*, *missing*." },
    { h: "Pages in a relto-library block" },
    { p: "One page per line: `page id: Label | effects | audio=… | unlock=[[Age]]:60`." },
    { code: "```relto-library\npage lagoon: Lagoon | vegetation 0.5 palm, gold 0.6 | audio=river | unlock=[[Marais de verre]]:60\n```" },
  ] },
  { id: "reltocat", part: "relto", icon: "cat", title: "The cat, the Imager and the telescope", body: [
    { h: "The cat" },
    { p: "Page `page_cat`. Three properties set it:" },
    { ul: ["`cat_name`: its name", "`cat_color`: black, white, orange, grey, cream, tabby, calico, tuxedo, siamese or #rrggbb", "`cat_sleep`: auto, always, never"] },
    { p: "In auto, it sleeps on the cabin rug mostly at night (even more with the Chimney page) and in rain, storm or snow; the draw changes every half hour. Click it and it purrs." },
    { p: "The koi pond (`page_koi`) has `koi_rare` (ogon, platinum, ghost) and `koi_name`." },
    { h: "The Imager" },
    { p: "Page `page_imager`: a machine on the cabin table, then its room. You set an Age's book on the lectern (‹ › to change book) and tune the machine until you see the Age on the brass screen." },
    { p: "No tabs: a workbench and three stations, each with its lamp; click to move closer, the down arrow to step back." },
    { ul: ["**I · Crystal rack**: eight engraved crystals, four slots; you pick up a crystal and place it (the one that was there returns to the rack). The right answer: the book's written pages, in block order (the first four). Wrong: the image doubles; a right page in the wrong place glows amber and counts a little", "**II · Optical bench**: three glasses (red, green, blue) that slide on their rails = the light of its star (sun colour, black sun, or no star); the slatted iris = the light received; the comparator shows the star on the left, your beam on the right. Wrong: the image is tinted or darkened", "**III · Regulator**: polarity inverter, frequency, amplitude, harmonics, phase; cathode-ray tube and voltmeter. Frequency comes from the length of the day, amplitude from the air pressure, harmonics from auroras and the magnetic field; the phase drifts with the hour (barely at all if the cycle is frozen; an erratic cycle jumps every two hours)"] },
    { p: "Sharpness is the product of the three: everything must be tuned; the gauge gives the overall figure." },
    { h: "Lock and periscope" },
    { ul: ["**Lock**: on a sharp image (amber lamp), pull the lever: the machine follows the Age on its own, the controls are held, and the book carries a brass tag on the shelf", "**Periscope** (locked): the crank turns the view (four directions, same sky, different scenery), the lever tilts it (zenith, horizon, underwater if there is water)"] },
    { p: "Clues: the surveyor's notebook on the cabin table, and the Age's Details tab (a surveyor's note, more or less precise depending on the “Surveyor's notes” setting). Tuning, lock and periscope are kept per book." },
    { p: "**Two voices**: at the Imager, the tuning fork on the console. Strike it: it keeps the voice of the sky of the Age on the machine, until the next strike. Find another world (another book, or other settings in the Art of the Guild) and strike it again: the two skies sing together, and the accord shows on the screen (an octave, a third, a tritone…; a purr when they sound as one, a chirp when they agree, a growl when they clash). Two strikes on the same world: unison. In the Art of the Guild, the ♪♪ button of the Details tab does the same, with a list."},
    { h: "The Art of the Guild" },
    { p: "The demanding way to play the instruments (setting `instrumentsMode: guild`; the default, easy mode is the Imager above). You do not choose the Age, you find it." },
    { ul: ["**The book**: the machine holds a single **blank book**, fixed in place (no ‹ ›), its window black", "**The telescope** gives the target: an Age's book on the observatory's lectern, its star already charted and the three wheels on its clues; the instrument holds that star and sends its light down. The station II comparator shows it on the left. Without it, the left half stays dark (you can still tune blind, from the surveyor's words)", "**Station I** offers crystals for the known glyphs (those written in the shelf's Ages, as in the book of glyphs; rows of eight, ‹ ›), four sockets: four crystals in order are the first pages of a world", "**Locking a planet**: when the crystals match an Age (among those of the held star, otherwise among all), they lock a planet and wake **station III**: only then does the sky's trace appear on the cathode tube", "**Shared stars**: several Ages around one star (`system:`) share its light; crystals and atmosphere tell them apart", "**Fully tuned**: the image forms and the book **remembers**: the Age's name is inscribed on its page"] },
    { p: "The sync micrometer (step 2), the lock and the periscope work as before." },
    { p: "Wrong crystals double the image, wrong glass tints it, a wrong atmosphere snows, without naming the world; settings that match no written Age usually leave the window black." },
    { h: "Worlds no one has written (the Art of the Guild)" },
    { p: "The Art links to worlds that already exist, so tuning blind (the telescope holds no star) with four crystals that match no written Age can still fall on one. Station III then searches instead of sleeping." },
    { p: "About one time in three, the window forms a world no one has written, provided that:" },
    { ul: ["the lenses name a plausible star", "the day and the air are plausible", "the book judges a world with these four first pages, in this order, alive"] },
    { p: "The same crystals, star light and notch ranges of iris, frequency and amplitude always show the same world, or nothing." },
    { p: "Brought into focus, it has no name in the book (“a world no one has written”, a few words of its description), a strange tone sounds and a line says so." },
    { p: "**Transcribe this world** writes a new note, never overwriting, with exactly its four pages, its star and sky as value lines (`star_mass:`, `insolation:`, `rotation:`, `atmosphere:`) and its `seed:`, under a generated name." },
    { p: "Opened, it is the same world, and a written Age from then on. A written Age whose pages match always wins." },
    { h: "The telescope" },
    { p: "Page `page_telescope`: always in the book of pages, locked until you have written a first Age and attached the Mountains page. A small observatory on the summit (stone drum, verdigris dome, open slit); click it to look through." },
    { h: "Step 1: find the Great Zero" },
    { p: "Every Relto hides its own **Great Zero**, drawn from its name and seed. Two wheels:" },
    { ul: ["**Torahn**: the angle, clockwise from the Great Zero line, in torantee (a full turn is 62,500)", "**Elevation**: height from the Great Zero plane, in shahfeetee (as on the KI, above the plane reads negative)"] },
    { p: "The rim moves 25 notches, the hub one notch (100 torantee or 1 shahfee). These are the D'ni Great Zero Coordinate System (GZCS) units; the third coordinate, the distance from the Zero (in shahfeetee), is measured when an Age's star is charted (below)." },
    { p: "No distance is ever shown: a pulse in the glass, beating with the D'ni prorahn, brightens and steadies as you come closer, a line of words says what you see, and a soft tone follows each turn. How much it tells you depends on the “Way of the instruments” setting:" },
    { ul: ["Easy way (default): the words add “It brightens.” or “It fades.” after each turn and the signal barely shimmers", "Art of the Guild: nothing says whether you are getting closer, the words say only three things (nothing, something, very close), and the signal shimmers from beat to beat, so watch a few beats and compare"] },
    { p: "On the left wall a brass **metronome**, set by hand, beats the prorahn: it counts, it does not know the hour. The true Zero's pulse peaks each time the pendulum reaches the end of its swing (the stop it touches glows; with the close-up room sounds, a dry tick distinct from the pulse's note); anything else slides against it. With reduced motion it stays at rest and a small lamp marks the beat." },
    { p: "Bring the point into the small ring: the Zero is found, engraved on the plate in D'ni numerals, and stays found (click the plate to set the wheels back on it)." },
    { h: "The D'ni clock" },
    { p: "Finding the Zero unlocks the **D'ni clock** page (`page_dni_clock`): a brass armillary sphere on its own pillar in the mist, its hour ring turning with the D'ni day. Once it is attached, the observatory spreads the Zero's beam through the whole Relto: the D'ni hour appears and the calendar sets itself right." },
    { p: "Until then the Relto only knows the date by its calendar pinnacle, which drifts by a few yahr, and the hour is silent. (That the beam carries D'ni time is this plugin's own extension of the lore.)" },
    { p: "Click the sphere to see it up close (the clock button in the navigation too): four brass rings carry the D'ni units, from the outside in:" },
    { ul: ["the vailee (one turn per hahr)", "the yahr (one per vailee)", "the gahrtahvo (one per yahr)", "the tahvo (one per gahrtahvo)"] },
    { p: "Each ring is engraved with its D'ni numerals and read under the fixed index at the top; when a unit changes, its digit glows for a moment, then fades. The plinth bears the date and hour in D'ni numerals and the vailee's name." },
    { h: "Step 2: chart an Age's star" },
    { p: "Once the Zero is found, lay an Age's book on the observatory's **lectern** (‹ ›). The wheels then aim where the Zero appears seen from that Age, and a third wheel sets the pulse's **Delay**, read in rahnfee as a lateness behind the metronome (a notch is a 625th of a rahnfee, 25 shahfeetee); an amber echo beats before or after the pulse until the delay is right." },
    { p: "The clues are in the Age's Details tab (direction, height, delay, faintness; values in D'ni numerals when the notes are full). The Age's **star is charted** (the instrument computes its GZCS position itself) when you are within:" },
    { ul: ["200 torantee", "2 shahfeetee", "one notch of delay"] },
    { p: "Ages with the same star blocks and the same `system: name` line share one star." },
    { p: "With the star charted, the Imager gains a **sync micrometer**: in sync, a sharper image, the hour over there (also in the Details tab) and the KIPS coordinates; it drifts after a real week (worn off after two), sync again. Without calibration the Imager is unchanged." },
    { h: "About distances" },
    { p: "The coordinates are those of the Great Zero Coordinate System, in shahfeetee — but for the Ages they are **shahfeetee of the beam**: the length of the path the pulse travels through the Art to reach the Zero, not a distance through space." },
    { p: "It is the Cavern's unit, measuring something else, so it has no equivalent in kilometres: a value of 15,000 means far along the beam, nothing more. The Art links worlds across universes, not across the sky; the Great Zero is the reference for that linking." },
    { h: "The rahnfee" },
    { p: "For these lengths of the beam the instruments use the **rahnfee** (plural *rahnfeetee*): the length the Great Zero's pulse travels along the beam in one **prorahn**, that is 25³ = **15,625 shahfeetee of the beam**." },
    { p: "There is no decimal point: each place is engraved in its own small window, like the dials of a surveyor's instrument:" },
    { ul: ["the first window counts 25ths", "the second 625ths", "the third 15,625ths"] },
    { p: "So the windows 12 · 12 · 12 read about half a rahnfee (7,812 shahfeetee); the instruments also say it in words (“about half a beat”). The windows are this plugin's own notation, as consistent as the D'ni surveyors' rigour, not an attested D'ni one." },
    { p: "Distances read in rahnfee:" },
    { ul: ["the Delay wheel", "the distance row of the *Great Zero* and *Star of the Age* plates", "the KIPS distance", "the surveyor's full notes", "the star chart"] },
    { p: "Every elevation stays in shahfeetee, the Cavern's scale and the KI's convention. *The rahnfee is a fan-made unit, built from prorahn and shahfee; not an attested D'ni word.*" },
    { h: "Far worlds" },
    { p: "About one star in six lies beyond a whole rahnfee; its pulse arrives a whole beat late, then a fraction. The Delay wheel only reads the fraction: the whole beats go on a small brass **counter** beside it (its digit is engraved bare before the windows)." },
    { p: "The pendulum is linked to the instrument: on each beat the **eyepiece crosshair glows** for an instant. The right delay is when the amber echo is born on the point at that flash. To read it, a **phase dial** is engraved in the glass: the flash sits at noon, and every beat that arrives leaves a mark where it is born, fading over a few beats. Easy way: a single live dot, and a line under the eyepiece says whether the echo comes before or after the pulse. Art of the Guild: not a word about the echo, you read it at the eyepiece and the metronome; the telescope is no calculator, it shows everything that crosses the Ages. The Zero's echo is always born at the same spot, so its marks pile into one sharp point; Me'erta's line (a beat at 1.06) walks slowly around the dial; near a dead star a pulsar crawls, a neutron star jumps. None of them piles up: **the true beat does not drift**. In the **Art of the Guild** a **turret of lenses** sits on the eyepiece barrel (a click turns it; Relto keeps the choice): the **bare glass** (the sky, the point, the crosshair), the **echo glass** (the amber echo magnified, to read its birth at a glance), the **phase plate** (the dial and its trace, the default) or **both**. The phase plate is cut from the same glass as the Imager's plates: the light of the pulse marks it for a moment, then the glass rests and forgets. Pile right of noon: the echo is born after, turn the Delay wheel right; left: before, turn left; on noon: set. Turning the wheel blurs the trace, which re-forms if you wait. Watch a few beats before deciding. To count them, watch the **strong beat** (the crosshair then glows gold): once a gorahn (every 25 beats) the Great Zero strikes harder and the pendulum's stroke glows gold; with the right count, the echo's strong beat comes back on that marked stroke, one stroke off otherwise." },
    { ul: ["Easy way: the surveyor's notes say so (“a whole beat late”) and a wrong count charts nothing", "Art of the Guild: a wrong count charts the star a whole rahnfee off, and the Imager cannot hold its planet (“the planet slips away by a whole beat”): count again and chart it again"] },
    { p: "Stars charted before far worlds existed keep their engraving." },
    { h: "Step 3: traps and difficulties" },
    { p: "This is the Art of the Guild; in the easy way there are no false pulses and dead stars only blur the image a little, the surveyor's notes telling the truth." },
    { h: "Dead stars" },
    { p: "Some regions of space hold a pulsar, a neutron star or a black hole (`pulsar`, `neutron_star`, `black_hole`), written or not; nearby stars share them." },
    { ul: ["A pulsar or neutron star adds a **false beat** at its own period (the surveyor's delay is wrong, and the amber echo can lock onto the false beat: nothing holds). The true echo pales under the false one, and even on the true delay the two beats stay tangled: the plate needs a **pose time**: three beats held still on the delay, and it engraves what it is shown. A sweep engraves nothing. Expose on the false beat and it **bites**: the star is engraved at the wrong distance (the direction is right), the map does not say so, but the Imager cannot hold its planet. Scratch the plate (the corner) or expose again on the true delay", "A black hole **bends** the Zero's light (the surveyor's direction is wrong; in the eyepiece a bright image will not hold, the true point is the pale end of the arc)"] },
    { p: "Such a star can still be charted by looking past the lure, or with the **beacons**: with two charted stars nearby, pull the lever; the instrument **marks** where the Zero should appear from here (a ghost ring in the eyepiece; close by but out of the field, a glow beating on the rim of the glass; a mark on the Delay wheel and on the dial) and **removes nothing**: the bent light and the false beat stay, the pose is still due. The prediction has its own error of a few notches; if one of the nearby stars was engraved wrong, it inherits it, and the trace contradicts it." },
    { h: "Early readings" },
    { p: "Not everything the instrument shows early on is what it seems: maybe you could explore and find out." },
    { h: "The star chart" },
    { p: "Star names are written on hover; the **Aa** button, on the right edge of the parchment, shows them all. A click on the parchment sets the **magnifier** there (×2, then ×4, then the whole chart). **N, E, S, W** look at a quarter of the sky; Under the magnifier, **drag the parchment** to move it. The **brass compass rose**, bottom right, turns the chart around the Zero: drag around it, or click it (Shift-click: the other way); right-drag or Shift-drag on the chart turns it too, and two fingers on a phone. Plumb lines stay upright; N, E, S, W keep their quarter of the sky. **◎** gives back the whole sky, north up. The scale adapts to your stars: those near the Zero spread out, the farthest stays at the edge, and directions stay true." },
    { p: "The parchment roll on the observatory wall opens a map of the Zero, your Relto and every charted star with its Ages (names on hover) and its dead stars, each hanging on a plumb line above or below the plane of the Zero (heights to their own scale); one well-charted Age anchors it." },
    { h: "Drift" },
    { ul: ["Ages without a magnetic field (dead core, or a world that does not spin) give rough bearings (four or eight compass words instead of sixteen) and their calibration wears twice as fast", "A weak field: 1.4 times as fast", "Near a dead star: faster still"] },
  ] },
  // ---- Spoilers ---------------------------------------------------------------------------------------------------
  { id: "spoilers", part: "spoil", icon: "eye-off", title: "Secrets of the Relto", spoiler: true,
    gate: { p: "Everything below spoils the game. None of it is needed to use the plugin: maybe you could just play and find out. If you would rather, leave the box unticked.", label: "Show the spoilers" }, body: [
    { h: "Getting in" },
    { p: "The hidden writing room needs the cabin. It opens once the story is finished (the inkwell), or in the sandbox when the page **Writing room** is active. The page **Inkwell** adds the mentor's last letter to the sandbox as well. Both are in the list of the command “Create a Relto page”." },
    { p: "The clue is scrawled on the back of the mentor's last letter, on the cabin table. It leads to the small bookcase under the window: touch three books in the right order, the one the sea dyed (blue), the one the fire left behind (red), the one with no title. The bookcase slides away. Behind it, a wooden panel answers to knocking: two quick knocks, a pause (between 0.75 and 2.8 seconds), then one firm knock." },
    { p: "Without the writing room, the bookcase is only a teaser: its books can be touched and do nothing." },
    { h: "The study key" },
    { p: "Once the riddle has been solved, **Settings › Age Writer › Relto** (and the Relto's own options) offer **Study key**. Switched on, a brass key lies on the cabin table and leads straight to the writing room. The riddle itself stays as it is." },
    { h: "Inside" },
    { ul: ["The desk (click the armchair to sit): a clickable lamp whose brass chain turns the light on and off, the orrery, the big book, the inkwell, a letter basket. The star chart opens from here and returns here.", "The ladder leads to the loft: the reference books (glyphs, library, book of pages, surveyor's notebook) sit on its long table once the room exists. At the end of the table, in the sandbox, a thick volume under a brass clasp: the **Treatise of the Art**. The clasp only gives to a Grand Master; the book then opens the whole reference without leaving the Relto.", "The round window, top left, shows the sky; with the **Comets** page active, a comet crosses it from time to time.", "The crystal flower in its oval frame, on the wall behind the desk: click it for a close-up. Its colours come from the Relto's seed. To change them without touching the seed, add `flower_color` to the note of the writing-room page: a hue (`flower_color: 200`) or a colour (`flower_color: \"#d04030\"`).", "The cat can sleep here instead of in the cabin: in its page, `cat_sleep: atelier` (or `atelier always`) keeps the hours of `auto` or `always` but picks the armchair, the rug or the bed, and changes spot every half hour."] },
    { p: "The cat can sleep here: `cat_sleep: atelier` (same sleeping hours, at a place that changes every half hour), or a fixed place: `atelier armchair`, `atelier rug`, `atelier bed` (e.g. `cat_sleep: atelier bed always`)." },
    { h: "The drawer and the stone" },
    { p: "A brass nail glows at the edge of the desk. It pulls out a drawer, where a black stone lies: the secret stone. Take it and it stays on the desk, in the room and in the desk view. It does nothing yet." },
    { h: "The observatory's false line" },
    { p: "Before you find the Zero, a second, paler pulse may catch your eye, slipping against the D'ni clock and the metronome (about 1.06 prorahn): the line of King Me'erta, never decreed. Lock onto it and the instrument holds that line: every star charted afterwards is turned by the same angle (the plate looks right, but the Age's hour and KIPS are wrong). The observatory's star chart reveals the trap." },
    { ul: ["On the star chart, the lead line from each star misses the Zero (“?”).", "Two stars engraved on different lines leave the chart unclosed; Ages of one `system:` disagree with a re-charted star; beacons engraved on different lines disagree.", "The Details tab says the star “was engraved on an old line”.", "To fix it: aim the true Zero again (the instrument settles on it and the old line will not take it back), then bring each star into the ring to re-engrave it, or scratch it off its plate (the small cross)."] },
    { h: "The mail" },
    { p: "The letter basket stands for a single note named **Courrier**. While the Relto is open, a letter from the mentor lands there at random, 8 to 25 minutes after the previous one (setting “Mentor's mail”: 2 to 6 or 30 to 90 minutes instead, or about one a day): it speaks of a block you do not know yet (three descriptors, a family, a name), and never of the final trial's blocks. A sealed envelope pulses on the desk until you read the note; reading it schedules the next." },
    { h: "Beneath the island" },
    { p: "**The recipes**, in words (the numbers stay yours to find): what gives light wants only the mineral, ash and silt (pure: volcanic ash, quartz silt, for it to come out clean), a little more ash than silt; a gentle fire, a long cooking, pressed hard: it sinks. What feeds wants only what has rotted, humus and peat, a little more humus than peat (one measure of hearth ash or volcanic silt is welcome), pressed lightly so it floats; a fire and a time in the middle, or a full batch, very short and very hot. Dust: it was not pressed enough. Grey: the mix or the fire is wrong. Change one thing at a time. A batch comes out clean only if every measure in it is rich, that is, given by an Age that was stable, without scar or sickness, that day." },
    { p: "**The lake**: an amber pellet leaves a colony in the water, never lost; fed in the last three days, the colonies pulse, forgotten they sleep as embers. About thirty fed colonies light the bottom band of the paintings without a flash and open a passage at the back of the lake; about two hundred give the cave back its light." },
    { p: "**The paintings**: your story in their signs, one sign per Age written (drawn from what it holds) and one per wonder seen; the most recent near the water. Each white flash seen from below lights one band more, upwards; at the very top, older than you, theirs." },
    { p: "**The code and the slab**: each flash shows two more signs of a six-sign code, painted along the pale vein on the left of the lake: start at the painted hand at its foot and read upwards. The code belongs to your Relto (its name and seed) and is written nowhere: remember it, or note it yourself. From the first flash, a slab lies in the water of the chamber of memories: six stones around a still basin. Start at the notch, follow the sun, turn each stone (one click, one notch) to the sign of the code. All six right: the water in the basin clears, for good." },
    { p: "**The chamber below**: through the passage the living lake opens, a round room, a starry pit, engraved pillars; the hanging basins light up with the lake, a few at the second degree, all at the third, and then two shadows stand by the crack. Look at the floor: you are at the edge of it." },
    { p: "**The dream**: with the basin clear and an Age locked on the Imager, look into the water: you see that Age from the other side, its faults already ripened, what another draw would have written, why its wonders hold. One dream per Age and per day; it fades on its own after a minute. Alone, nothing stays. Take along an orb of a wonder seen in that same Age (select it in the chamber: “Take it into the dream”) and, on waking, the panel offers one line per thing you looked at closely: a fault to correct, a block to write, a wonder's sentence for its orb. Nothing is written unless you choose it." },
    { h: "The second book" },
    { p: "After the ninth chapter, a second book of letters: **10** cook a white pellet (gold page; in a story Relto the machine waits for this letter, and only the Ages of its folder fill its hoppers), **11** see a flash from below (silver page), **12** feed the lake and look at a drop under the microscope (gems page), **13** open the slab (no page: the slab is the prize). Chapter 10 has three hints; the others are places to explore." },
    { h: "Easter eggs" },
    { p: "**Marcel.** Give the cat page a black cat named Marcel (`cat_name: Marcel`, `cat_color: black`): a page that shows itself to no one else appears in the Pages tab, its name in gold, a paw beside it. Turn it on. Marcel is a hospital cat: he keeps the book of the Age that is worst off (sick first, then the lowest stability under 50 %), and when he sleeps the book leaves the shelf and he sleeps on it; he stays with it as long as that Age is unwell. By day he has the colour of leather, and a slow wave of black runs from his head to his tail with each deep breath; at dusk the black wins; at night he is a black cat. The hearth crackles." },
  ] },
];

module.exports = { REF_EN };
